'use strict';

// MODULES //

var map = require( '@stdlib/array/base/map' );
var symbol2shorthand = require( '@stdlib/plot/base/symbol2shorthand' );


// MAIN //

/**
* Converts an array of symbol aliases and/or shorthands to symbol shorthands.
*
* ## Notes
*
* -   If unable to resolve a shorthand for an element of the input array, the corresponding element in the output array is `null`.
*
* @param {Collection<string>} symbols - symbol aliases and/or shorthands
* @returns {Array} symbol shorthands
*
* @example
* var v = symbols2shorthands( [ 'circle', 'square' ] );
* // returns [ 'o', 's' ]
*
* v = symbols2shorthands( [ 'circle', 'beep' ] );
* // returns [ 'o', null ]
*/
function symbols2shorthands( symbols ) {
	return map( symbols, symbol2shorthand );
}


// EXPORTS //

module.exports = symbols2shorthands;
